<?php
$root=dirname(__DIR__);$fail=[];$check=function($ok,$name)use(&$fail){echo($ok?'PASS':'FAIL')." — {$name}\n";if(!$ok)$fail[]=$name;};
$schema=file_get_contents($root.'/database/schema.sql');foreach(['organisations','platform_users','memberships','identity_sessions','products','applications','application_redirect_uris','product_tenants','domains','service_accounts','features','plans','prices','subscriptions','entitlement_grants','usage_meters','invoices','payments','payment_attempts','refunds','webhook_events','audit_events','error_events','outbox_events','jobs','impersonation_grants','application_heartbeats','rate_limits']as$t)$check(str_contains($schema,'CREATE TABLE IF NOT EXISTS '.$t),'schema table '.$t);
$check(str_contains($schema,'normalized_hostname VARCHAR(253) NOT NULL'),'normalized hostname stored');$check(str_contains($schema,'UNIQUE KEY uk_domain_hostname(normalized_hostname)'),'global domain uniqueness');$check(str_contains($schema,'service_access_state VARCHAR(32)'),'service-access state separated');$check(str_contains($schema,'token_hash BINARY(32)'),'service token stored as hash');
$app=file_get_contents($root.'/app/App.php');foreach(['/internal/v1/domains/resolve','/internal/v1/memberships/verify','/internal/v1/impersonation/consume','/internal/v1/usage','/internal/v1/heartbeats','/internal/v1/audit','/internal/v1/errors','/health/live','/health/ready']as$r)$check(str_contains($app,$r),'route '.$r);$check(!str_contains($app,'$_GET[\'tenant_guid\']'),'no direct tenant selection from query parameter');$check(str_contains($app,"ServiceAuth::requireScope('domains.resolve')"),'domain resolver service scope');$check(str_contains(file_get_contents($root.'/app/Core/OAuth.php'),'code_challenge'),'PKCE authorization code flow');
$check(!is_file($root.'/config/config.php'),'release does not ship production secrets');$check(is_file($root.'/public_html/install.php'),'browser installer present');$check(is_file($root.'/public_html/.htaccess'),'front-controller rewrite present');$check(is_file($root.'/bin/worker.php')&&is_file($root.'/bin/scheduler.php'),'worker and scheduler present');exit($fail?1:0);
